/**
 * Writes `fixtures/package/v14/services.buildbox`, its `project.json` and its asset (#79 §1).
 *
 * Run it with `npx vite-node scripts/make-v14-package-fixture.ts`. The file is an ordinary production
 * Backup — the format this build writes — so any build can run the generator. Like every golden file
 * it is committed bytes, never regenerated by a test; `fixtures.test.ts` proves these bytes still
 * round-trip.
 *
 * The scene is the v13 one beside it, unchanged, with the one thing the fourteenth schema added
 * spelled out on the Floor the scene already carries: four Services of the Existing Model — a round
 * Run, a rectangular Run, a Riser and a Run below the Floor Datum — and one Run a Design Option owns.
 * It is the bytes the round-trip of a Project that holds a Service is judged against.
 */
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { canonicalJsonBytes } from '../src/lib'
import { encodeProject } from '../src/package/encode'
import { FIXTURE_BUILD, FIXTURE_PLAN_IMAGE_HASH, servicesFixtureProject } from '../src/package/testing'

const assetBytes = readFileSync(join('fixtures', 'package', 'v8', 'assets', `${FIXTURE_PLAN_IMAGE_HASH}.png`))
const assetSource = async (): Promise<{ bytes: Uint8Array; mediaType: string }> => ({
  bytes: new Uint8Array(assetBytes),
  mediaType: 'image/png',
})

const project = servicesFixtureProject()
const bytes = await encodeProject(project, assetSource, FIXTURE_BUILD)

const dir = join('fixtures', 'package', 'v14')
mkdirSync(join(dir, 'assets'), { recursive: true })
writeFileSync(join(dir, 'services.buildbox'), bytes)
writeFileSync(join(dir, 'project.json'), `${new TextDecoder().decode(canonicalJsonBytes(project))}\n`)
copyFileSync(join('fixtures', 'package', 'v8', 'assets', `${FIXTURE_PLAN_IMAGE_HASH}.png`), join(dir, 'assets', `${FIXTURE_PLAN_IMAGE_HASH}.png`))
console.info(`wrote ${join(dir, 'services.buildbox')}: ${String(bytes.length)} bytes`)
